create type public.app_role as enum ('admin','cashier');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null default 'Staff');
grant select,update on public.profiles to authenticated; grant all on public.profiles to service_role;
alter table public.profiles enable row level security;
create table public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null default 'cashier');
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
create policy own_roles on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.has_role(auth.uid(),'admin'));
create policy profiles_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create function public.new_staff() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','Staff')); insert into public.user_roles(user_id,role) values(new.id,'cashier'); return new; end $$;
create trigger new_staff after insert on auth.users for each row execute function public.new_staff();
create sequence public.tag_seq; create sequence public.invoice_seq; create sequence public.loan_seq; create sequence public.receipt_seq;
create table public.metal_types(id uuid primary key default gen_random_uuid(),name text unique not null);
grant select,insert,update,delete on public.metal_types to authenticated; grant all on public.metal_types to service_role; alter table public.metal_types enable row level security;
create policy metals_read on public.metal_types for select to authenticated using(true); create policy metals_admin on public.metal_types for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.daily_rates(date date not null,metal_id uuid references public.metal_types not null,rate_per_gram numeric(16,2) not null check(rate_per_gram>0),primary key(date,metal_id));
grant select,insert,update on public.daily_rates to authenticated; grant all on public.daily_rates to service_role; alter table public.daily_rates enable row level security;
create policy rates_read on public.daily_rates for select to authenticated using(true); create policy rates_admin on public.daily_rates for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.items(id uuid primary key default gen_random_uuid(),tag_id text unique not null default ('JW-'||lpad(nextval('public.tag_seq')::text,5,'0')),name text not null check(length(trim(name))>0),metal_id uuid references public.metal_types not null,weight numeric(12,3) not null check(weight>0),supplier text,photo_url text,status text not null default 'In Stock' check(status in ('In Stock','Sold')),sold_invoice text,created_at timestamptz default now());
grant select on public.items to authenticated; grant all on public.items to service_role; alter table public.items enable row level security; create policy items_read on public.items for select to authenticated using(true);
create table public.item_costs(item_id uuid primary key references public.items on delete cascade,purchase_price numeric(16,2) not null check(purchase_price>=0));
grant select on public.item_costs to authenticated; grant all on public.item_costs to service_role; alter table public.item_costs enable row level security; create policy costs_admin on public.item_costs for select to authenticated using(public.has_role(auth.uid(),'admin'));
create table public.customers(id uuid primary key default gen_random_uuid(),name text not null,phone text unique not null);
grant select on public.customers to authenticated; grant all on public.customers to service_role; alter table public.customers enable row level security; create policy customers_read on public.customers for select to authenticated using(true);
create table public.sales(id uuid primary key default gen_random_uuid(),invoice_no text unique not null default ('INV-'||lpad(nextval('public.invoice_seq')::text,5,'0')),date date default (now() at time zone 'Asia/Colombo')::date,customer_id uuid references public.customers,payment_type text not null,payment_method text not null,calculated_total numeric(16,2) not null,final_total numeric(16,2) not null,paid_now numeric(16,2) not null,loan_amount numeric(16,2) not null,created_by uuid not null,created_at timestamptz default now());
grant select on public.sales to authenticated; grant all on public.sales to service_role; alter table public.sales enable row level security; create policy sales_read on public.sales for select to authenticated using(public.has_role(auth.uid(),'admin') or created_by=auth.uid());
create table public.sale_items(id uuid primary key default gen_random_uuid(),sale_id uuid references public.sales not null,item_id uuid references public.items not null unique,tag_id text not null,name text not null,metal text not null,weight numeric(12,3) not null,rate_used numeric(16,2) not null,calculated_price numeric(16,2) not null,final_price numeric(16,2) not null);
grant select on public.sale_items to authenticated; grant all on public.sale_items to service_role; alter table public.sale_items enable row level security; create policy lines_read on public.sale_items for select to authenticated using(exists(select 1 from public.sales where id=sale_id));
create table public.sale_costs(sale_item_id uuid primary key references public.sale_items not null,purchase_cost numeric(16,2) not null);
grant select on public.sale_costs to authenticated; grant all on public.sale_costs to service_role; alter table public.sale_costs enable row level security; create policy sale_cost_admin on public.sale_costs for select to authenticated using(public.has_role(auth.uid(),'admin'));
create table public.loans(id uuid primary key default gen_random_uuid(),loan_no text unique not null default ('LN-'||lpad(nextval('public.loan_seq')::text,5,'0')),sale_id uuid references public.sales not null,customer_id uuid references public.customers not null,amount numeric(16,2) not null,frequency text not null,status text default 'Active',created_at timestamptz default now());
grant select on public.loans to authenticated; grant all on public.loans to service_role; alter table public.loans enable row level security; create policy loans_read on public.loans for select to authenticated using(true);
create table public.loan_installments(id uuid primary key default gen_random_uuid(),loan_id uuid references public.loans not null,installment_no int not null,due_date date not null,amount numeric(16,2) not null,unique(loan_id,installment_no));
grant select on public.loan_installments to authenticated; grant all on public.loan_installments to service_role; alter table public.loan_installments enable row level security; create policy installments_read on public.loan_installments for select to authenticated using(true);
create table public.loan_payments(id uuid primary key default gen_random_uuid(),loan_id uuid references public.loans not null,receipt_no text unique default ('RC-'||lpad(nextval('public.receipt_seq')::text,5,'0')),date date default (now() at time zone 'Asia/Colombo')::date,amount numeric(16,2) not null check(amount>0),method text not null,received_by uuid not null);
grant select on public.loan_payments to authenticated; grant all on public.loan_payments to service_role; alter table public.loan_payments enable row level security; create policy payments_read on public.loan_payments for select to authenticated using(true);
create table public.settings(id boolean primary key default true check(id),shop_name text not null default 'Jewellery POS',address text default '',phone text default '',currency text default 'LKR');
grant select,insert,update on public.settings to authenticated; grant all on public.settings to service_role; alter table public.settings enable row level security; create policy settings_admin on public.settings for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create function public.shop_public_details() returns jsonb language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Sign in required'; end if; return coalesce((select to_jsonb(s) from public.settings s limit 1),'{"shop_name":"Jewellery POS","address":"","phone":"","currency":"LKR"}'::jsonb); end $$;
create function public.setup_owner() returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Sign in required'; end if; perform pg_advisory_xact_lock(882233); if exists(select 1 from public.user_roles where role='admin') then raise exception 'An owner is already configured'; end if; update public.user_roles set role='admin' where user_id=auth.uid(); insert into public.settings(id) values(true) on conflict do nothing; insert into public.metal_types(name) values('22K Gold'),('24K Gold'),('18K Gold'),('Silver') on conflict do nothing; end $$;
create function public.save_item(p jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare iid uuid; begin if not public.has_role(auth.uid(),'admin') then raise exception 'Admin only'; end if; if p->>'id' is not null then iid:=(p->>'id')::uuid; perform 1 from public.items where id=iid and status='In Stock' for update; if not found then raise exception 'Only in-stock pieces can be edited'; end if; update public.items set name=p->>'name',metal_id=(p->>'metal_id')::uuid,weight=(p->>'weight')::numeric,supplier=p->>'supplier',photo_url=p->>'photo_url' where id=iid; else insert into public.items(name,metal_id,weight,supplier,photo_url) values(p->>'name',(p->>'metal_id')::uuid,(p->>'weight')::numeric,p->>'supplier',p->>'photo_url') returning id into iid; end if; insert into public.item_costs values(iid,(p->>'purchase_price')::numeric) on conflict(item_id) do update set purchase_price=excluded.purchase_price; return iid; end $$;
create function public.delete_item(iid uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not public.has_role(auth.uid(),'admin') then raise exception 'Admin only'; end if; delete from public.items where id=iid and status='In Stock'; if not found then raise exception 'Only in-stock pieces can be deleted'; end if; end $$;
create function public.complete_sale(p jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare sid uuid; cid uuid; lid uuid; lineid uuid; r record; j jsonb; total numeric:=0; calc numeric:=0; rate numeric; cp numeric; fp numeric; paid numeric; n int; k int; firstdate date; due date; base numeric; loan numeric; inv text; today date:=(now() at time zone 'Asia/Colombo')::date; begin if not exists(select 1 from public.user_roles where user_id=auth.uid()) then raise exception 'Staff login required'; end if; if jsonb_array_length(p->'lines')=0 then raise exception 'Add at least one piece'; end if; if (select count(distinct x->>'id') from jsonb_array_elements(p->'lines') x)<>jsonb_array_length(p->'lines') then raise exception 'Duplicate piece'; end if; perform 1 from public.items where id in(select (x->>'id')::uuid from jsonb_array_elements(p->'lines') x) order by id for update;
for j in select * from jsonb_array_elements(p->'lines') loop select * into r from public.items where id=(j->>'id')::uuid; if not found or r.status<>'In Stock' then raise exception 'Piece not found or already sold'; end if; select rate_per_gram into rate from public.daily_rates where date=today and metal_id=r.metal_id; if rate is null then raise exception 'Today’s metal rate is missing'; end if; fp:=round((j->>'final_price')::numeric,2); if fp is null or fp<0 then raise exception 'Invalid final price'; end if; select purchase_price into cp from public.item_costs where item_id=r.id; if fp<cp and coalesce((p->>'confirm_below_cost')::boolean,false)=false then raise exception 'BELOW_COST'; end if; total:=total+fp; calc:=calc+round(r.weight*rate,2); end loop;
if total<=0 then raise exception 'Bill total must be positive'; end if; paid:=round((p->>'paid_now')::numeric,2); if p->>'payment_type'='Full Payment' then paid:=total; elsif p->>'payment_type'='Full Loan' then paid:=0; elsif p->>'payment_type'='Cash + Loan' then if paid is null or paid<=0 or paid>=total then raise exception 'Paid now must be between zero and total'; end if; else raise exception 'Invalid payment type'; end if; if p->>'payment_method' not in('Cash','Card','Bank Transfer','Mixed') then raise exception 'Invalid payment method'; end if; loan:=total-paid;
if loan>0 and (nullif(trim(p->>'customer_name'),'') is null or nullif(trim(p->>'customer_phone'),'') is null) then raise exception 'Customer name and phone required for loans'; end if;
if nullif(trim(p->>'customer_phone'),'') is not null then insert into public.customers(name,phone) values(coalesce(nullif(trim(p->>'customer_name'),''),'Customer'),trim(p->>'customer_phone')) on conflict(phone) do update set name=excluded.name returning id into cid; end if;
insert into public.sales(customer_id,payment_type,payment_method,calculated_total,final_total,paid_now,loan_amount,created_by) values(cid,p->>'payment_type',p->>'payment_method',calc,total,paid,loan,auth.uid()) returning id,invoice_no into sid,inv;
for j in select * from jsonb_array_elements(p->'lines') loop select i.*,m.name metal into r from public.items i join public.metal_types m on m.id=i.metal_id where i.id=(j->>'id')::uuid; select rate_per_gram into rate from public.daily_rates where date=today and metal_id=r.metal_id; insert into public.sale_items(sale_id,item_id,tag_id,name,metal,weight,rate_used,calculated_price,final_price) values(sid,r.id,r.tag_id,r.name,r.metal,r.weight,rate,round(r.weight*rate,2),round((j->>'final_price')::numeric,2)) returning id into lineid; insert into public.sale_costs select lineid,purchase_price from public.item_costs where item_id=r.id; update public.items set status='Sold',sold_invoice=inv where id=r.id; end loop;
if loan>0 then n:=(p->>'installments')::int; if n is null or n<1 or n>120 then raise exception 'Installments must be 1–120'; end if; if p->>'frequency' not in('Monthly','Every 2 weeks','Weekly') then raise exception 'Invalid frequency'; end if; firstdate:=(p->>'first_due')::date; if firstdate is null or firstdate<today then raise exception 'Invalid first due date'; end if; insert into public.loans(sale_id,customer_id,amount,frequency) values(sid,cid,loan,p->>'frequency') returning id into lid; base:=floor(loan*100/n)/100; for k in 1..n loop if p->>'frequency'='Monthly' then due:=(date_trunc('month',firstdate)+(k-1)*interval '1 month')::date; due:=due+least(extract(day from firstdate)::int,extract(day from (due+interval '1 month - 1 day'))::int)-1; else due:=firstdate+(k-1)*case when p->>'frequency'='Weekly' then 7 else 14 end; end if; insert into public.loan_installments(loan_id,installment_no,due_date,amount) values(lid,k,due,case when k=n then loan-base*(n-1) else base end); end loop; end if; return sid; end $$;
create function public.record_payment(p jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare l record; balance numeric; a numeric; rid uuid; begin if not exists(select 1 from public.user_roles where user_id=auth.uid()) then raise exception 'Staff login required'; end if; select * into l from public.loans where id=(p->>'loan_id')::uuid for update; if not found then raise exception 'Loan not found'; end if; select l.amount-coalesce(sum(amount),0) into balance from public.loan_payments where loan_id=l.id; a:=round((p->>'amount')::numeric,2); if a is null or a<=0 or a>balance then raise exception 'Payment must be positive and not exceed balance'; end if; if p->>'method' not in('Cash','Card','Bank Transfer','Mixed') then raise exception 'Invalid method'; end if; insert into public.loan_payments(loan_id,amount,method,received_by) values(l.id,a,p->>'method',auth.uid()) returning id into rid; if a=balance then update public.loans set status='Closed' where id=l.id; end if; return rid; end $$;
create function public.set_staff_role(uid uuid,new_role public.app_role) returns void language plpgsql security definer set search_path=public as $$ begin if not public.has_role(auth.uid(),'admin') then raise exception 'Admin only'; end if; if uid=auth.uid() then raise exception 'Cannot change your own role'; end if; update public.user_roles set role=new_role where user_id=uid; end $$;
revoke execute on all functions in schema public from public,anon; grant execute on function public.has_role(uuid,public.app_role),public.shop_public_details(),public.setup_owner(),public.save_item(jsonb),public.delete_item(uuid),public.complete_sale(jsonb),public.record_payment(jsonb),public.set_staff_role(uuid,public.app_role) to authenticated;